/**
 * The seven botanical plates, as drawn.
 *
 * These replace the procedurally generated plant. What changed and why it
 * matters is recorded here rather than in a commit message, because there is no
 * repository yet:
 *
 *  - The plates arrived as complete 320x560 designs: a sage ground, a soil
 *    band, the plant, and a caption set as vector text. Only the ground, the
 *    soil and the plant are kept. The baked-in captions are deliberately
 *    dropped: the app renders its own from describeDaisy(), which is live,
 *    selectable and reachable by a screen reader, and two captions disagreeing
 *    with each other is worse than none.
 *
 *  - Every colour is a token (AC-63). The plates' own hexes were added to the
 *    botanical family in index.css rather than approximated with the existing
 *    greens, because approximating them would have quietly redrawn the art.
 *
 *  - The sage ground is part of the drawing, not decoration. White rays on the
 *    page's sand cannot be told apart from it; on the sage they can. See the
 *    contrast note in index.css.
 *
 * Coordinates are the plates' own, cropped to 0 0 320 460 — the caption band is
 * gone, the soil runs to the bottom edge. All seven share that frame on purpose:
 * the plant growing INSIDE a fixed frame is the whole metaphor, so the seed must
 * look like a small thing in a large space.
 */

export const ART_VIEWBOX = '0 0 320 460';

/** The soil band and its grit. Common to all seven plates. */
function Ground() {
  return (
    <g>
      <rect y="390" width="320" height="70" fill="var(--c-soil)" />
      <ellipse cx="46" cy="414" rx="3" ry="2" fill="var(--c-soil-grit)" />
      <ellipse cx="104" cy="436" rx="4" ry="3" transform="rotate(24 104 436)" fill="var(--c-soil-grit)" />
      <ellipse cx="212" cy="408" rx="5" ry="2" transform="rotate(48 212 408)" fill="var(--c-soil-grit)" />
      <circle cx="268" cy="430" r="3" fill="var(--c-soil-grit)" />
      <ellipse cx="146" cy="444" rx="4" ry="2" transform="rotate(96 146 444)" fill="var(--c-soil-grit)" />
      <ellipse cx="190" cy="420" rx="5" ry="3" transform="rotate(120 190 420)" fill="var(--c-soil-grit)" />
    </g>
  );
}

