/** Disc florets: [cx, cy, r, opacity]. Drawn from data rather than 20 hand-written
 *  circles, so the two discs differ in one array instead of forty elements. */
type Floret = [number, number, number, number];

function Florets({ seeds }: { seeds: readonly Floret[] }) {
  return (
    <g fill="var(--c-disc-edge)">
      {seeds.map(([cx, cy, r, o], i) => (
        <circle key={i} cx={cx} cy={cy} r={r} fillOpacity={o} />
      ))}
    </g>
  );
}

