// --- the plate set ----------------------------------------------------------

/**
 * Indexed by Stage.n, so a stage number from daisy.ts picks its plate directly
 * and a stage that gains a plate later cannot silently render the wrong one.
 */
const PLATES: Record<number, () => React.JSX.Element> = {
  1: Seed,
  2: Germination,
  3: Seedling,
  4: Vegetative,
  5: Bud,
  6: FirstRays,
  7: FullBloom,
};

export function plateFor(stageN: number): () => React.JSX.Element {
  return PLATES[stageN] ?? Seed;
}
